// الفصل الثاني: الجمعُ والطرح
import { AR, fmt, rnd, pick, shuf } from './mathkit.js';
import { $, $$, num, lst, mcq, ch, open, fld, calc, star } from './engine.js';
import { fr } from './algebra.js';
import { KB, T2, A, MX, r10, placeQ, expQ, wordQ, cmpS, nlSVG, roundQ, roundTo, estQ, addQ, decCol, modelSVG, modelTool, placeName, sortedStr } from './kit5.js';

const ordQ = (tag, text, arr, o = {}) => lst(tag, text, sortedStr(arr, o.desc).map(Number), { skill: 'order', sol: [sortedStr(arr, o.desc).map(A).join('، ')], ...o });
const propQ = (tag, expr, k, o = {}) => ch(tag, o.text || `ما خاصّيّةُ الجمعِ المستعملةُ في: <span class="mx"><b class="n">${AR(expr)}</b></span>`, ['الخاصّيّةُ الإبداليّة', 'الخاصّيّةُ التجميعيّة', 'خاصّيّةُ العنصرِ المحايدِ الجمعيّ'], k, { skill: 'prop', sol: [['تغيّرَ ترتيبُ العددين فقط.', 'تغيّرَ العددانِ اللذانِ نبدأُ بهما الجمع (موضعُ الأقواس).', 'جمعْنا صفرًا فبقيَ العددُ نفسُه.'][k]], ...o });
const mental = (tag, expr, v, how, o = {}) => num(tag, o.text || `استعملْ خصائصَ الجمعِ لإيجادِ المجموعِ ذهنيًّا: <span class="mx"><b class="n">${AR(expr)}</b></span>`, v, { skill: 'mental', sol: how, ...o });
const bal = (tag, a, op, b, o = {}) => { const r = r10(op === '+' ? a + b : a - b, 4); return num(tag, o.text || `${op === '+' ? 'اجمعْ' : 'اطرحْ'} ذهنيًّا مستعملًا الموازنة: <span class="mx"><b class="n">${AR(String(a))}</b><i class="op">${op === '+' ? '+' : '−'}</i><b class="n">${AR(String(b))}</b></span>`, r, { skill: 'bal', sol: [balHow(a, op, b), `الناتج: ${fmt(r)}`], ...o }); };
function balHow(a, op, b) { // نغيّرُ العددَ الأقربَ إلى عددٍ «سهل»
  const step = Number.isInteger(a) && Number.isInteger(b) ? 10 : 1; const near = x => { const up = Math.ceil(x / step) * step; return r10(up - x, 4); };
  if (op === '+') { const [x, y] = near(b) <= near(a) ? [b, a] : [a, b]; const d = near(x); if (!d) return `${AR(a)} + ${AR(b)}`; return `نضيفُ ${fmt(d)} إلى ${fmt(x)} ونطرحُ ${fmt(d)} من ${fmt(y)}: ${fmt(r10(x + d, 4))} + ${fmt(r10(y - d, 4))} = ${fmt(r10(a + b, 4))}`; }
  const d = near(b); if (!d) return `${fmt(a)} − ${fmt(b)}`; return `نضيفُ ${fmt(d)} إلى كلا العددين: ${fmt(r10(a + d, 4))} − ${fmt(r10(b + d, 4))} = ${fmt(r10(a - b, 4))}`;
}
const back = (tag, text, v, steps, o = {}) => num(tag, text, v, { skill: 'back', sol: steps, hints: ['ابدأْ من النهاية (المعطى الأخير)، واعملِ العمليّاتِ العكسيّةَ خطوةً خطوة.'], ...o });

/* ═════════ المولّدات ═════════ */
const G = {
  round: L => { if (Math.random() < .5) { const n = String(rnd(L ? 1000 : 10, L ? 999999 : 9999)); const p = rnd(1, n.length - 1); return roundQ('', n, p); } const s = (rnd(1, 99) + rnd(1, 999) / 1000).toFixed(3).replace(/0+$/, ''); const d = (s.split('.')[1] || '').length; return roundQ('', s, -rnd(0, Math.max(0, d - 1))); },
  est: L => { const op = pick(['+', '-']); let a, b; if (Math.random() < .5) { a = rnd(100, L ? 9999 : 999); b = rnd(10, a - 1); } else { a = r10(rnd(100, 9999) / 100, 2); b = r10(rnd(10, Math.floor(a * 100) - 1) / 100, 2); } const step = a >= 1000 ? 100 : a >= 100 ? 10 : 1; const e = op === '+' ? roundTo(a, Math.log10(step)) + roundTo(b, Math.log10(step)) : roundTo(a, Math.log10(step)) - roundTo(b, Math.log10(step)); return estQ('', `${a} ${op} ${b}`, r10(e, 2)); },
  dadd: L => { const a = (rnd(1, L ? 99 : 20) + rnd(0, 999) / 1000).toFixed(rnd(1, 3)), b = (rnd(0, L ? 50 : 10) + rnd(1, 99) / 100).toFixed(rnd(1, 2)); return addQ('', +a, +b, '+'); },
  dsub: L => { let a = +(rnd(5, L ? 99 : 30) + rnd(0, 99) / 100).toFixed(rnd(1, 2)), b = +(rnd(0, Math.floor(a) - 1) + rnd(1, 999) / 1000).toFixed(rnd(1, 3)); if (b >= a) b = r10(a / 2, 2); return addQ('', a, b, '-'); },
  prop: L => { const a = rnd(2, 60), b = rnd(2, 60), c = rnd(2, 60); const k = rnd(0, 2); const e = k === 0 ? `${a} + ${b} = ${b} + ${a}` : k === 1 ? `(${a} + ${b}) + ${c} = ${a} + (${b} + ${c})` : `${a} + 0 = ${a}`; return propQ('', e, k); },
  mental: L => { const t = rnd(1, 8) * 10 + 5, a = rnd(11, 89); const b = 100 - t; return mental('', `${t} + ${a} + ${b}`, t + a + b, [`نجمعُ ${AR(t)} و${AR(b)} أوّلًا (متناغمان): ${AR(t)} + ${AR(b)} = ١٠٠`, `١٠٠ + ${AR(a)} = ${AR(100 + a)}`]); },
  bal: L => { const op = pick(['+', '-']); if (L && Math.random() < .5) { const a = r10(rnd(20, 99) + rnd(1, 9) / 10, 1), b = r10(rnd(2, 19) + pick([0.8, 0.9, 0.7]), 1); return bal('', op === '-' && b > a ? b : a, op, op === '-' && b > a ? a : b); } const a = rnd(100, 999), b = rnd(1, 9) * 10 + pick([7, 8, 9]); return bal('', a, op, b); },
  back: L => { const n = rnd(3, 30), c = pick([2, 3, 4, 5, 10, 15]), f = rnd(5, 120), start = n * c + f; return back('', `مع سعيدٍ مبلغٌ من المال، دفعَ منه ${AR(f)} ريالًا أجرةَ توصيل، واشترى بالباقي كتبًا ثمنُ الواحدِ ${AR(c)} ريالات، فاشترى ${AR(n)} كتابًا ولم يبقَ معه شيء. كم ريالًا كان معه؟`, start, [`نبدأُ من النهاية: ${AR(n)} × ${AR(c)} = ${AR(n * c)}`, `ثم نضيفُ الأجرة: ${AR(n * c)} + ${AR(f)} = ${AR(start)}`]); },
};
const GN = { round: 'التقريب', est: 'تقدير الجمع والطرح', dadd: 'جمع الكسور العشرية', dsub: 'طرح الكسور العشرية', prop: 'خصائص الجمع', mental: 'الجمع الذهني', bal: 'الموازنة', back: 'الحل عكسيًّا' };

